"use client";

import React, { useState, useMemo } from "react";
import { 
  Calendar as CalendarIcon, 
  Users, 
  Clock, 
  CheckCircle2, 
  AlertTriangle, 
  X, 
  ArrowRight, 
  FileText,
  PieChart,
  Briefcase,
  ChevronRight,
  Sparkles
} from "lucide-react";

// --- MOCK DATA (Context: India/Global Tech) ---
const HOLIDAYS = [
  { date: "2026-01-26", name: "Republic Day" }, // Monday
];

const TEAM_OVERLAP = [
  { name: "Amit Patel", role: "Backend Lead", dates: ["2026-01-14", "2026-01-16"], img: "bg-blue-600" },
  { name: "Sarah Jenkins", role: "Product Manager", dates: ["2026-01-20", "2026-01-22"], img: "bg-purple-600" }
];

const LEAVE_TYPES = [
  { id: "annual", label: "Annual Leave", balance: 18, color: "text-blue-600", accrual: "+1.5/mo" },
  { id: "sick", label: "Sick Leave", balance: 12, color: "text-rose-600", accrual: "+1.0/mo" },
  { id: "casual", label: "Casual Leave", balance: 6, color: "text-amber-600", accrual: "Fixed" },
];

export default function UltimateAbsencePortal() {
  const [viewState, setViewState] = useState<"dashboard" | "form">("dashboard");
  const [selection, setSelection] = useState<{ start: string; end: string }>({ start: "", end: "" });
  const [reqData, setReqData] = useState({ type: "annual", reason: "", handoff: "", autoDecline: true });

  // --- LOGIC: The "Brain" of the page ---
  const calculation = useMemo(() => {
    if (!selection.start || !selection.end) return { days: 0, holidays: 0, weekends: 0, conflicts: 0 };
    
    let days = 0, holidays = 0, weekends = 0;
    let cur = new Date(selection.start);
    let end = new Date(selection.end);
    let conflicts = 0;

    while (cur <= end) {
      const dateStr = cur.toISOString().split('T')[0];
      const day = cur.getDay();
      
      // Check Holiday
      if (HOLIDAYS.find(h => h.date === dateStr)) holidays++;
      // Check Weekend (Sat/Sun)
      else if (day === 0 || day === 6) weekends++;
      // Check Workday
      else {
        days++;
        // Check Team Conflict (Simple logic: is anyone else out this specific day?)
        const isConflict = TEAM_OVERLAP.some(p => p.dates.includes(dateStr));
        if (isConflict) conflicts++;
      }
      cur.setDate(cur.getDate() + 1);
    }
    return { days, holidays, weekends, conflicts };
  }, [selection]);

  // Calendar Selection Logic
  const handleDayClick = (dateStr: string) => {
    if (viewState === "form") return; // Lock during input
    if (!selection.start || (selection.start && selection.end)) {
      setSelection({ start: dateStr, end: "" });
    } else {
      const s = new Date(selection.start);
      const e = new Date(dateStr);
      if (e < s) setSelection({ start: dateStr, end: "" });
      else setSelection({ ...selection, end: dateStr });
    }
  };

  return (
    <div className="min-h-screen bg-[#F8F9FC] p-4 lg:p-8 font-sans text-slate-900">
      
      {/* 1. HEADER: Elite Context */}
      <header className="mx-auto max-w-[1600px] mb-8 flex items-center justify-between">
        <div>
           <h1 className="text-2xl font-black tracking-tight text-slate-900">Request Absence</h1>
           <p className="text-xs font-bold uppercase tracking-widest text-slate-400">Hyderabad HQ • Engineering</p>
        </div>
        <div className="flex gap-3">
           <div className="hidden md:flex items-center gap-2 rounded-full bg-white px-4 py-2 text-xs font-bold text-slate-600 shadow-sm border border-slate-100">
              <span className="h-2 w-2 rounded-full bg-emerald-500 animate-pulse"/>
              System Operational
           </div>
           <div className="flex items-center gap-2 rounded-full bg-white px-4 py-2 text-xs font-bold text-slate-600 shadow-sm border border-slate-100">
              <Briefcase className="h-4 w-4 text-slate-400" />
              Approver: <span className="text-slate-900">Sarah Jenkins (Avg. 2h)</span>
           </div>
        </div>
      </header>

      <div className="mx-auto max-w-[1600px] grid grid-cols-12 gap-8 h-[calc(100vh-140px)] min-h-[600px]">
        
        {/* 2. LEFT PANE: The "Playground" (Calendar) */}
        <div className="col-span-12 lg:col-span-8 flex flex-col">
          <div className="flex-1 rounded-[2rem] border border-slate-200 bg-white p-8 shadow-sm relative overflow-hidden">
             
             <div className="flex justify-between items-end mb-8">
                <h2 className="text-4xl font-black text-slate-800">January 2026</h2>
                <div className="flex gap-4 text-[10px] font-bold uppercase tracking-widest text-slate-400">
                   <div className="flex items-center gap-2"><div className="w-3 h-3 bg-blue-600 rounded-md"/>Selected</div>
                   <div className="flex items-center gap-2"><div className="w-3 h-3 bg-orange-400 rounded-md"/>Holiday</div>
                   <div className="flex items-center gap-2"><div className="w-3 h-3 bg-slate-100 border rounded-md"/>Weekend</div>
                </div>
             </div>

             {/* CALENDAR GRID */}
             <div className="grid grid-cols-7 h-[80%] gap-1">
                {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(d => (
                  <div key={d} className="text-center text-xs font-black text-slate-300 uppercase mb-2">{d}</div>
                ))}
                
                {/* Jan 1 2026 is Thu -> 3 empty slots */}
                {[null, null, null].map((_,i) => <div key={`e-${i}`}/>)}

                {Array.from({ length: 31 }).map((_, i) => {
                   const day = i + 1;
                   const dateStr = `2026-01-${day < 10 ? `0${day}` : day}`;
                   const dateObj = new Date(2026, 0, day);
                   const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6;
                   const holiday = HOLIDAYS.find(h => h.date === dateStr);
                   const isSelected = selection.start === dateStr || selection.end === dateStr;
                   const inRange = selection.start && selection.end && dateStr > selection.start && dateStr < selection.end;

                   return (
                     <button
                       key={day}
                       onClick={() => handleDayClick(dateStr)}
                       disabled={viewState === "form"}
                       className={`
                         relative rounded-xl text-left p-3 transition-all duration-300 border
                         ${isSelected ? "bg-blue-600 text-white border-blue-600 shadow-xl shadow-blue-200 z-10 scale-105" : ""}
                         ${inRange ? "bg-blue-50 text-blue-700 border-blue-50" : ""}
                         ${holiday && !inRange && !isSelected ? "bg-orange-50 border-orange-100" : ""}
                         ${isWeekend && !isSelected && !inRange ? "bg-slate-50 border-transparent opacity-60" : "border-slate-100 hover:border-blue-300 bg-white"}
                       `}
                     >
                        <span className="text-sm font-bold">{day}</span>
                        {holiday && !inRange && <span className="absolute bottom-2 left-2 text-[9px] font-bold text-orange-500 uppercase">{holiday.name}</span>}
                     </button>
                   )
                })}
             </div>

             {/* FLOATING ACTION BAR */}
             {selection.start && selection.end && viewState === "dashboard" && (
                <div className="absolute bottom-8 left-8 right-8 bg-slate-900 text-white p-4 rounded-2xl flex items-center justify-between shadow-2xl animate-in slide-in-from-bottom-4">
                   <div className="flex gap-8 items-center px-4">
                      <div>
                         <p className="text-[10px] font-bold uppercase text-slate-400">Total Duration</p>
                         <p className="font-bold">{calculation.days + calculation.holidays + calculation.weekends} Days</p>
                      </div>
                      <div className="h-8 w-px bg-white/20"/>
                      <div>
                         <p className="text-[10px] font-bold uppercase text-slate-400">Leave Deducted</p>
                         <p className="font-bold text-blue-400">{calculation.days} Days</p>
                      </div>
                      {calculation.holidays > 0 && (
                         <div className="flex items-center gap-2 text-emerald-400 text-xs font-bold bg-emerald-400/10 px-3 py-1 rounded-full">
                            <Sparkles className="w-3 h-3" /> Includes {calculation.holidays} Public Holiday
                         </div>
                      )}
                   </div>
                   <div className="flex gap-2">
                      <button onClick={() => setSelection({start:"", end:""})} className="px-6 py-3 text-xs font-bold text-slate-400 hover:text-white uppercase">Cancel</button>
                      <button onClick={() => setViewState("form")} className="bg-blue-600 hover:bg-blue-500 text-white px-8 py-3 rounded-xl font-bold text-xs uppercase tracking-wide transition-all">
                         Continue
                      </button>
                   </div>
                </div>
             )}
          </div>
        </div>

        {/* 3. RIGHT PANE: Context Switching */}
        <div className="col-span-12 lg:col-span-4 flex flex-col h-full">
          
          {/* MODE A: DASHBOARD (Before selection) */}
          {viewState === "dashboard" && (
             <div className="flex flex-col gap-6 h-full animate-in fade-in">
                
                {/* Balance Card */}
                <div className="bg-white p-6 rounded-[2rem] border border-slate-200 shadow-sm flex-1">
                   <h3 className="text-lg font-black text-slate-800 mb-6 flex items-center gap-2">
                      <PieChart className="w-5 h-5 text-slate-400" /> My Balances
                   </h3>
                   <div className="space-y-6">
                      {LEAVE_TYPES.map(t => (
                         <div key={t.id}>
                            <div className="flex justify-between text-xs font-bold mb-2">
                               <span className="text-slate-500">{t.label}</span>
                               <span className="text-slate-900">{t.balance} Days</span>
                            </div>
                            <div className="h-2 w-full bg-slate-100 rounded-full overflow-hidden">
                               <div className={`h-full bg-current ${t.color}`} style={{width: '60%'}}/>
                            </div>
                            <p className="mt-1 text-[10px] text-slate-400 font-medium">Accrues {t.accrual}</p>
                         </div>
                      ))}
                   </div>
                </div>

                {/* Team Status Card */}
                <div className="bg-white p-6 rounded-[2rem] border border-slate-200 shadow-sm flex-1">
                   <h3 className="text-lg font-black text-slate-800 mb-6 flex items-center gap-2">
                      <Users className="w-5 h-5 text-slate-400" /> Team Pulse
                   </h3>
                   {calculation.conflicts > 0 ? (
                      <div className="bg-amber-50 border border-amber-100 p-4 rounded-xl mb-4">
                         <div className="flex gap-3">
                            <AlertTriangle className="w-5 h-5 text-amber-600" />
                            <div>
                               <p className="text-xs font-bold text-amber-800">High Overlap Detected</p>
                               <p className="text-[10px] text-amber-700 leading-tight mt-1">
                                  {calculation.conflicts} team members are also out during your selection. Approval may be delayed.
                               </p>
                            </div>
                         </div>
                      </div>
                   ) : (
                      <p className="text-xs text-slate-400 mb-4">Upcoming team absences:</p>
                   )}
                   
                   <div className="space-y-3">
                      {TEAM_OVERLAP.map((m, i) => (
                         <div key={i} className="flex items-center justify-between p-3 rounded-xl bg-slate-50">
                            <div className="flex items-center gap-3">
                               <div className={`w-8 h-8 rounded-full flex items-center justify-center text-white text-xs font-bold ${m.img}`}>
                                  {m.name.charAt(0)}
                               </div>
                               <div>
                                  <p className="text-xs font-bold text-slate-900">{m.name}</p>
                                  <p className="text-[10px] text-slate-500">{m.role}</p>
                               </div>
                            </div>
                            <span className="text-[10px] font-bold bg-white border px-2 py-1 rounded">
                               {m.dates[0].slice(5)}
                            </span>
                         </div>
                      ))}
                   </div>
                </div>
             </div>
          )}

          {/* MODE B: REQUEST FORM (After selection) */}
          {viewState === "form" && (
             <div className="bg-white h-full rounded-[2rem] border border-slate-200 shadow-xl p-8 flex flex-col animate-in slide-in-from-right-4">
                <div className="flex justify-between items-center mb-6">
                   <h2 className="text-xl font-black text-slate-800">Finalize Request</h2>
                   <button onClick={() => setViewState("dashboard")} className="p-2 hover:bg-slate-100 rounded-full">
                      <X className="w-5 h-5 text-slate-400" />
                   </button>
                </div>

                <div className="flex-1 space-y-6 overflow-y-auto">
                   
                   {/* 1. Type Selector */}
                   <div className="space-y-2">
                      <label className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Leave Type</label>
                      <div className="grid grid-cols-2 gap-3">
                         {LEAVE_TYPES.map(t => (
                            <button 
                              key={t.id}
                              onClick={() => setReqData({...reqData, type: t.id})}
                              className={`p-3 rounded-xl border-2 text-left transition-all ${
                                 reqData.type === t.id ? "border-blue-600 bg-blue-50" : "border-slate-100 hover:border-slate-200"
                              }`}
                            >
                               <span className={`block text-xs font-black ${reqData.type === t.id ? "text-blue-700" : "text-slate-700"}`}>{t.label}</span>
                               <span className="text-[10px] text-slate-400">{t.balance} Days avail</span>
                            </button>
                         ))}
                      </div>
                   </div>

                   {/* 2. Reason & Handoff (The Elite Additions) */}
                   <div className="space-y-2">
                      <label className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Context</label>
                      <textarea 
                        className="w-full rounded-xl border border-slate-200 p-3 text-sm font-medium focus:ring-2 focus:ring-blue-500 outline-none min-h-[80px]"
                        placeholder="Reason for absence (Optional for Annual)"
                        value={reqData.reason}
                        onChange={(e) => setReqData({...reqData, reason: e.target.value})}
                      />
                   </div>

                   <div className="space-y-2">
                      <label className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Work Handoff <span className="text-rose-500">*</span></label>
                      <div className="relative">
                         <input 
                           type="text"
                           className="w-full rounded-xl border border-slate-200 p-3 text-sm font-medium focus:ring-2 focus:ring-blue-500 outline-none pl-10"
                           placeholder="@Mention a colleague..."
                           value={reqData.handoff}
                           onChange={(e) => setReqData({...reqData, handoff: e.target.value})}
                         />
                         <Users className="w-4 h-4 text-slate-400 absolute left-3 top-3.5" />
                      </div>
                      <p className="text-[10px] text-slate-400">This ensures tasks don't stall while you are away.</p>
                   </div>

                   {/* 3. Automation Toggles */}
                   <div className="bg-slate-50 p-4 rounded-xl space-y-3">
                      <label className="flex items-center gap-3 cursor-pointer">
                         <div className={`w-5 h-5 rounded border flex items-center justify-center ${reqData.autoDecline ? "bg-blue-600 border-blue-600" : "bg-white border-slate-300"}`}>
                            {reqData.autoDecline && <CheckCircle2 className="w-3.5 h-3.5 text-white" />}
                         </div>
                         <input type="checkbox" className="hidden" checked={reqData.autoDecline} onChange={() => setReqData({...reqData, autoDecline: !reqData.autoDecline})} />
                         <span className="text-xs font-bold text-slate-700">Auto-decline meetings</span>
                      </label>
                      <div className="text-[10px] text-slate-400 pl-8">
                         We will automatically update your Slack status and block your GCal.
                      </div>
                   </div>

                </div>

                <div className="pt-6 border-t border-slate-100">
                   <button className="w-full bg-slate-900 hover:bg-black text-white py-4 rounded-xl font-bold text-sm flex items-center justify-center gap-2 transition-all">
                      Submit Request <ArrowRight className="w-4 h-4" />
                   </button>
                </div>
             </div>
          )}
        </div>
      </div>
    </div>
  );
}